$('desktop-password-form').onsubmit=async e=>{e.preventDefault();if(!authorized())return;const request=desktopRequest,account=owner(),action=desktopPendingAction,input=$('desktop-password-value'),button=$('desktop-password-confirm');if(button.disabled)return;button.disabled=true;try{let ok=false;const password=input.value;input.value='';if(window.pfdAssert&&window.parent?.pfdConfirmPassword){window.pfdAssert();ok=await window.parent.pfdConfirmPassword(password);window.pfdAssert()}else{const cfg=obterConfigProtecao();if(!cfg?.ativo)throw Error('Configure a senha em Segurança e Acesso.');ok=await validarSenha(password,cfg)}if(request!==desktopRequest||!$('desktop-password').open||account!==owner()||!authorized())return;if(!ok)throw Error('Senha incorreta. Tente novamente.');$('desktop-password').close();desktopPendingAction=null;action?.()}catch(err){if(request===desktopRequest&&$('desktop-password').open)$('desktop-password-error').textContent=err.message||'Não foi possível validar.'}finally{input.value='';button.disabled=false}};
