function chart(m,alt=null){if(m.opening===null)return '<div class="empty">Abertura por tipo de pessoa não informada. Os totais de movimentação continuam disponíveis.</div>';const p=m.daily,a=alt?.daily||[],v=[0,m.opening,...p.map(d=>d.balance),...a.map(d=>d.balance)],lo=Math.min(...v),hi=Math.max(...v),span=hi-lo||1,x=i=>85+i*715/Math.max(1,p.length-1),y=n=>200-(n-lo)/span*165;let s='<svg class="chart" viewBox="0 0 850 245" role="img" aria-label="Saldo acumulado por vencimento">';[lo,(lo+hi)/2,hi].forEach(n=>s+='<line class="grid" x1="85" x2="800" y1="'+y(n)+'" y2="'+y(n)+'"/><text x="75" y="'+(y(n)+4)+'" text-anchor="end">'+(n/100000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mil</text>');s+='<line class="zero" x1="85" x2="800" y1="'+y(0)+'" y2="'+y(0)+'"/><polyline class="base" points="'+p.map((d,i)=>x(i)+','+y(d.balance)).join(' ')+'"/>';if(a.length)s+='<polyline class="alt" points="'+a.map((d,i)=>x(i)+','+y(d.balance)).join(' ')+'"/>';[0,9,19,p.length-1].forEach(i=>{if(p[i])s+='<text x="'+x(i)+'" y="229" text-anchor="middle">'+br(p[i].date).slice(0,5)+'</text>';});if(m.critical){const i=p.findIndex(d=>d.date===m.critical.date);s+='<circle cx="'+x(i)+'" cy="'+y(m.critical.balance)+'" r="4" fill="var(--red)"><title>'+fmt(m.critical.balance)+' em '+br(m.critical.date)+'</title></circle>';}return s+'</svg>';}
const reportStyles='body{font:14px/1.5 "Segoe UI",system-ui,sans-serif;margin:25px auto;max-width:1100px;padding:0 20px;color:#243247;background:#fff}h1,h2{color:#203c64}h1{font-size:25px}h2{font-size:18px}table{width:100%;border-collapse:collapse;font-size:12px;margin:15px 0}td,th{text-align:left;border-bottom:1px solid #d7e1ee;padding:8px}th{background:#203c64;color:#fff}.chart{width:100%;height:250px}.chart text{fill:#526176;font:11px system-ui}.chart .grid{stroke:#d7e1ee}.chart .zero{stroke:#526176}.chart .base{fill:none;stroke:#203c64;stroke-width:3}:root{--red:#bd2b20}button{padding:9px 14px;background:#203c64;color:#fff;border:0;border-radius:6px;cursor:pointer}@media print{@page{size:A4 landscape;margin:12mm}button{display:none}body{padding:0;margin:0}tr,.chart{break-inside:avoid}thead{display:table-header-group}}';

const gNames={from:'Data inicial',to:'Data final',type:'Tipo',category:'Rubrica',status:'Status',description:'Descrição',min:'Valor mínimo',max:'Valor máximo'},gIds={from:'gFrom',to:'gTo',type:'gType',category:'gCategory',status:'gStatus',description:'gDescription',min:'gMin',max:'gMax'};
let gApplied={from:'2026-11-01',to:'2026-11-30',type:'',category:'',status:'',description:'',min:'',max:''},gMode='period',gHistoryScope='filtered',gFocus=null,gPage=0,gSort={field:'vencimento',desc:false},gUpdated='',gViews={};
function gScope(){return rows.filter(t=>entity()==='Todas'||t.entidade===entity());}function gContent(t,f=gApplied){return (!f.type||t.tipo===f.type)&&(!f.category||t.categoria===f.category)&&(!f.status||C.status(t,cut())===f.status)&&(!f.description||(t.descricao||'').toLocaleLowerCase('pt-BR').includes(f.description.toLocaleLowerCase('pt-BR')))&&(f.min===''||C.cents(t)>=Math.round(Number(f.min)*100))&&(f.max===''||C.cents(t)<=Math.round(Number(f.max)*100));}
function gRead(){return Object.fromEntries(Object.entries(gIds).map(([k,id])=>[k,$(id).value.trim()]));}function gFill(f){Object.entries(gIds).forEach(([k,id])=>$(id).value=f[k]??'');}function gHasContent(f=gApplied){return ['type','category','status','description','min','max'].some(k=>f[k]!=='');}
function gData(f=gApplied){const all=gScope().filter(t=>gContent(t,f)),range=all.filter(t=>t.vencimento>=f.from&&t.vencimento<=f.to),active=range.filter(t=>C.cents(t)!==0),pending=all.filter(t=>(!t.vencimento||t.vencimento>=f.from&&t.vencimento<=f.to)&&(!t.vencimento||C.cents(t)===0)),sum=a=>a.reduce((s,t)=>s+C.cents(t),0),rec=active.filter(t=>t.tipo==='Receita'),des=active.filter(t=>t.tipo==='Despesa'),inv=active.filter(t=>t.tipo==='Investimentos');return {all,active,pending,rec,des,inv,r:sum(rec),d:sum(des),investment:sum(inv),out:sum(des)+sum(inv),received:sum(rec.filter(C.paid)),paid:sum(des.filter(C.paid)),due:sum(des.filter(t=>!C.paid(t)&&t.vencimento>=cut())),late:sum(des.filter(t=>!C.paid(t)&&t.vencimento<cut())),result:sum(rec)-sum(des)-sum(inv)};}
function gMetric(label,v,note='',klass='',help=''){return '<div class="g-metric"><div class="label">'+esc(label)+(help?'<button data-g-help="'+help+'" aria-label="Explicar indicador">ⓘ</button>':'')+'</div><div class="number '+klass+'">'+v+'</div><small>'+note+'</small></div>';}
function gApply(){const f=gRead();if(!/^\d{4}-\d{2}-\d{2}$/.test(f.from)||!/^\d{4}-\d{2}-\d{2}$/.test(f.to)||f.from>f.to){$('gError').textContent='Informe um período válido: início não pode ser posterior ao fim.';return false;}if(C.days(f.from,f.to)>366){$('gError').textContent='Selecione até 367 dias por análise.';return false;}if((f.min!==''&&(!Number.isFinite(Number(f.min))||Number(f.min)<0))||(f.max!==''&&(!Number.isFinite(Number(f.max))||Number(f.max)<0))||(f.min!==''&&f.max!==''&&Number(f.min)>Number(f.max))){$('gError').textContent='Revise os valores mínimo e máximo.';return false;}gApplied={...f};gMode=$('gMode').value;gHistoryScope=$('gHistoryScope').value;gUpdated=new Date().toLocaleString('pt-BR');gFocus=null;gPage=0;$('gError').textContent='';$('gPending').textContent='';gRender();return true;}
function gMarkDirty(){$('gPending').textContent='Alterações pendentes. Clique em Aplicar filtros para atualizar a análise.';}
function gHistoryData(){const ref=C.date(gApplied.to.slice(0,7)+'-01'),scoped=gScope(),known=new Set(historyCoverage()),a=[];for(let i=11;i>=0;i--){const d=new Date(ref);d.setUTCMonth(d.getUTCMonth()-i);const key=C.iso(d).slice(0,7),[start,end]=C.range(key),consulted=gHistoryScope==='twelve'||end>=gApplied.from&&start<=gApplied.to,covered=known.has(key),monthRows=consulted&&covered?scoped.filter(t=>gContent(t)&&t.vencimento?.startsWith(key)&&(gHistoryScope==='twelve'||t.vencimento>=gApplied.from&&t.vencimento<=gApplied.to)&&C.cents(t)!==0):[],r=monthRows.filter(t=>t.tipo==='Receita').reduce((s,t)=>s+C.cents(t),0),out=monthRows.filter(t=>t.tipo!=='Receita').reduce((s,t)=>s+C.cents(t),0);a.push({key,label:d.toLocaleDateString('pt-BR',{month:'short',year:'2-digit',timeZone:'UTC'}),consulted,covered,rows:monthRows,r,out});}return a;}
function gHistoryHTML(){const a=gHistoryData(),max=Math.max(1,...a.flatMap(m=>[m.r,m.out]));return a.map(m=>'<div class="g-month '+(!m.consulted||!m.covered?'nd':'')+'"><b>'+esc(m.label)+'</b>'+(!m.consulted?'<p>Fora do recorte</p>':!m.covered?'<p>Histórico N/D</p>':!m.rows.length?'<p>Sem registros</p>':'<div class="monthbars"><i style="background:var(--green);height:'+m.r/max*65+'px"></i><i style="background:var(--red);height:'+m.out/max*65+'px"></i></div><small>R '+fmt(m.r)+'<br>S '+fmt(m.out)+'<br>Resultado '+fmt(m.r-m.out)+'</small>')+'</div>').join('');}
function gCash(){const all=gScope(),d=gData(),opening=!gHasContent()&&gApplied.from?all.filter(t=>t.vencimento&&t.vencimento<gApplied.from).reduce((s,t)=>s+C.signed(t),0):null;let acc=opening;const daily=[];for(let day=gApplied.from;day<=gApplied.to;day=C.add(day,1)){const entries=d.active.filter(t=>t.vencimento===day),r=entries.filter(t=>t.tipo==='Receita').reduce((s,t)=>s+C.cents(t),0),out=entries.filter(t=>t.tipo!=='Receita').reduce((s,t)=>s+C.cents(t),0);if(acc!==null)acc+=r-out;daily.push({date:day,r,out,balance:acc});}return {opening,closing:acc,daily,critical:opening===null?null:daily.reduce((a,d)=>!a||d.balance<a.balance?d:a,null)};}
function gBars(items){const max=Math.max(1,...items.map(x=>Math.abs(x.value)));return items.map(x=>'<div class="bar"><div class="row"><b>'+esc(x.label)+'</b><b class="'+(x.value<0?'neg':'')+'">'+fmt(x.value)+'</b></div><div class="track"><span style="width:'+Math.abs(x.value)/max*100+'%;background:'+(x.value<0?'var(--red)':'var(--green)')+'"></span></div></div>').join('');}
function gMain(){const d=gData();if(gMode==='cash'){$('gMainTitle').textContent='Evolução do caixa por vencimento';$('gMainChart').innerHTML=chart(gCash());$('gModeNote').textContent='Abertura calculada pelos lançamentos anteriores ao período, no tipo de pessoa selecionado. Não é saldo bancário conciliado. Filtros de conteúdo não definem uma abertura de caixa; nesses casos o acumulado fica N/D.';return;}if(gMode==='previous'){const ref=C.date(gApplied.to.slice(0,7)+'-01'),current=C.iso(ref).slice(0,7);ref.setUTCMonth(ref.getUTCMonth()-1);const prev=C.iso(ref).slice(0,7),known=new Set(historyCoverage());$('gMainTitle').textContent='Mês anterior × mês atual';$('gMainChart').innerHTML=[prev,current].map(key=>{const [from,to]=C.range(key);if(!known.has(key))return '<div class="subtle"><b>'+key+'</b><p>Histórico não fornecido nesta análise. Comparação e variação: N/D.</p></div>';const m=gData({...gApplied,from,to});return '<h3>'+key+'</h3>'+gBars([{label:'Receitas',value:m.r},{label:'Saídas',value:-m.out},{label:'Resultado',value:m.result}]);}).join('');$('gModeNote').textContent='Compara meses completos e mantém os filtros de conteúdo. Não transforma ausência de histórico em zero. Variação percentual só pode ser calculada com bases comparáveis e base anterior diferente de zero.';return;}$('gMainTitle').textContent=gMode==='comparison'?'Receitas × saídas cadastradas':'Receitas, saídas e resultado do período';$('gMainChart').innerHTML=gBars(gMode==='comparison'?[{label:'Receitas cadastradas',value:d.r},{label:'Saídas cadastradas',value:-d.out}]:[{label:'Receitas cadastradas',value:d.r},{label:'Dedução das saídas',value:-d.out},{label:'Resultado previsto',value:d.result}]);$('gModeNote').textContent='Comparativo de barras independentes, não uma cascata encadeada. Não considera saldo inicial. Saídas incluem despesas e investimentos.';}
function gAlertHTML(print=false){const d=gData(),future=d.active.filter(t=>!C.paid(t)&&t.vencimento>=cut()),next=future.filter(t=>t.tipo==='Receita').sort((a,b)=>a.vencimento.localeCompare(b.vencimento))[0],before=next?future.filter(t=>t.tipo!=='Receita'&&t.vencimento<next.vencimento):[],amount=before.reduce((s,t)=>s+C.cents(t),0),income=next?future.filter(t=>t.tipo==='Receita'&&t.vencimento===next.vencimento).reduce((s,t)=>s+C.cents(t),0):0,dups=duplicates(d.active);return '<div class="g-alert"><h3>Pagamentos antes dos recebimentos</h3>'+(next?'<strong>'+fmt(amount)+'</strong><p>em saídas pendentes antes da entrada prevista de <b>'+fmt(income)+'</b>, em <b>'+br(next.vencimento)+'</b>.</p>':'<p>Não há entrada futura em aberto identificada nos filtros atuais.</p>')+'<p>Saldo disponível conciliado não informado; não foi calculada uma necessidade real de crédito. O alerta respeita o período, tipo de pessoa e filtros selecionados.</p>'+(!print&&before.length?'<button data-g-drill="before">Ver lançamentos</button>':'')+'</div>'+dups.map((a,i)=>'<div class="g-alert secondary"><h3>Conferir registros semelhantes</h3><strong>'+a.length+' registros de '+esc(a[0].descricao)+' · '+fmt(C.cents(a[0]))+' cada</strong><p>Vencimento: '+br(a[0].vencimento)+'. A coincidência não comprova erro ou duplicidade.</p>'+(!print?'<button data-g-dup="'+i+'">Conferir lançamentos</button>':'')+'</div>').join('');}
function gRankData(){const g=new Map();gData().active.filter(t=>t.tipo!=='Receita').forEach(t=>{const key=t.categoria||'Sem rubrica';g.set(key,(g.get(key)||0)+C.cents(t));});return [...g].sort((a,b)=>b[1]-a[1]);}
function gRankingHTML(print=false){const a=gRankData(),total=a.reduce((s,x)=>s+x[1],0),max=Math.max(1,...a.map(x=>x[1])),percent=$('gRankingUnit').value==='percent';return a.map(([name,value])=>'<'+(print?'div':'button')+' class="g-rank-row"'+(print?'':' data-g-category="'+esc(name)+'"')+'><div class="row"><span>'+esc(name)+'</span><b>'+(percent?pct(value,total)+' · '+fmt(value):fmt(value)+' · '+pct(value,total))+'</b></div><div class="track"><span style="width:'+value/max*100+'%"></span></div></'+(print?'div':'button')+'>').join('')||'<p class="note">Sem saídas neste recorte.</p>';}
function gHeatHTML(print=false){const a=gData().active,g=new Map();for(let day=gApplied.from;day<=gApplied.to;day=C.add(day,1)){const entries=a.filter(t=>t.vencimento===day),r=entries.filter(t=>t.tipo==='Receita').reduce((s,t)=>s+C.cents(t),0),out=entries.filter(t=>t.tipo!=='Receita').reduce((s,t)=>s+C.cents(t),0);g.set(day,{r,out});}const max=Math.max(0,...[...g.values()].map(d=>d.out));return '<div class="g-heat">'+[...g].map(([day,d])=>'<'+(print?'div':'button')+' class="g-day '+(d.out?'has ':'')+(max>0&&d.out===max?'max':'')+'"'+(print?'':' data-g-date="'+day+'"')+'><b>'+br(day).slice(0,5)+'</b><small>S '+fmt(d.out)+'</small>'+($('gHeatKind').value==='both'?'<small class="pos">R '+fmt(d.r)+'</small>':'')+'</'+(print?'div':'button')+'>').join('')+'</div>';}


function gDetailRows(){let a=gData().active;if(gFocus)a=a.filter(t=>gFocus.ids.includes(t.id));const value=t=>gSort.field==='valor'?C.cents(t):gSort.field==='status'?C.status(t,cut()):String(t[gSort.field]||'');return a.slice().sort((a,b)=>{const x=value(a),y=value(b),n=typeof x==='number'?x-y:x.localeCompare(y,'pt-BR');return gSort.desc?-n:n;});}
function gTable(a,actions=true){return '<div class="tablewrap"><table><thead><tr>'+[['vencimento','Vencimento'],['categoria','Rubrica'],['descricao','Descrição'],['status','Status'],['valor','Valor']].map(([f,label])=>'<th>'+(actions?'<button data-g-sort="'+f+'">'+label+(gSort.field===f?(gSort.desc?' ▾':' ▴'):'')+'</button>':label)+'</th>').join('')+(actions?'<th>Cadastro original</th>':'')+'</tr></thead><tbody>'+a.map(t=>'<tr><td>'+br(t.vencimento)+'</td><td>'+esc(t.categoria)+'</td><td>'+esc(t.descricao)+'</td><td>'+esc(!t.vencimento||C.cents(t)===0?t.status||'Pendente':C.status(t,cut()))+'</td><td class="num">'+fmt(C.cents(t))+'</td>'+(actions?'<td><button data-g-edit="'+t.id+'">Abrir cadastro</button></td>':'')+'</tr>').join('')+'</tbody></table></div>';}
function gRenderDetail(){const a=gDetailRows(),size=Number($('gPageSize').value)||10,pages=Math.max(1,Math.ceil(a.length/size));gPage=Math.max(0,Math.min(gPage,pages-1));const view=a.slice(gPage*size,(gPage+1)*size);$('gDetail').innerHTML=view.length?gTable(view):'<p class="empty">Nenhum registro neste recorte de detalhamento.</p>';$('gDrillNote').innerHTML=gFocus?'<p class="subtle"><b>Consulta: '+esc(gFocus.label)+'</b> <button id="gBackDrill">Voltar à análise completa</button><br><small>Os filtros da análise foram preservados.</small></p>':'';if(gFocus)$('gBackDrill').onclick=()=>{gFocus=null;gPage=0;gRenderDetail();};$('gDetailTotals').innerHTML=totals(a);$('gPageLabel').textContent=a.length?('Mostrando '+(gPage*size+1)+'–'+(gPage*size+view.length)+' de '+a.length+' · Página '+(gPage+1)+'/'+pages):'0 registros';$('gPrevPage').disabled=gPage===0;$('gNextPage').disabled=gPage>=pages-1;const pending=gData().pending;$('gDataIssues').innerHTML=pending.length?'<div class="tablewrap"><table><thead><tr><th>Cadastro</th><th>Problema a conferir</th><th>Valor</th><th>Ação</th></tr></thead><tbody>'+pending.map(t=>'<tr><td>'+esc(t.descricao)+'</td><td>'+(!t.vencimento?'Sem vencimento. ':'')+(C.cents(t)===0?'Valor zero.':'')+'</td><td>'+fmt(C.cents(t))+'</td><td><button data-g-edit="'+t.id+'">Corrigir cadastro</button></td></tr>').join('')+'</tbody></table></div>':'<p class="note">Nenhuma pendência corresponde aos filtros.</p>';}
function gDrill(ids,label){gFocus={ids,label};gPage=0;gRenderDetail();$('gDetail').scrollIntoView({behavior:'smooth',block:'center'});}
function gFiltersText(){return br(gApplied.from)+' a '+br(gApplied.to)+' · Tipo de pessoa: '+entity()+Object.entries(gApplied).filter(([k,v])=>!['from','to'].includes(k)&&v!=='').map(([k,v])=>' · '+gNames[k]+': '+v).join('');}
function gRender(){const draftCategory=$('gCategory').value;$('gCategory').innerHTML='<option value="">Todas</option>'+[...new Set([...rows.map(t=>t.categoria),...(draftCategory?[draftCategory]:[])])].sort().map(c=>'<option>'+esc(c)+'</option>').join('');$('gCategory').value=draftCategory;gUpdated=new Date().toLocaleString('pt-BR');const d=gData();$('gMovement').innerHTML=gMetric('Receitas cadastradas',fmt(d.r),'Inclui recebidas','pos')+gMetric('Receitas recebidas',fmt(d.received),pct(d.received,d.r)+' das receitas','pos')+gMetric('Despesas cadastradas',fmt(d.d),'Investimentos são separados')+gMetric('Despesas pagas',fmt(d.paid),pct(d.paid,d.d)+' das despesas')+gMetric('Resultado previsto',fmt(d.result),'Receitas − despesas − investimentos',d.result<0?'neg':'pos');$('gAttention').innerHTML=gMetric('Despesas a vencer',fmt(d.due),'Em aberto, a partir da referência')+gMetric('Despesas vencidas',fmt(d.late),'Em aberto, anteriores à referência',d.late?'neg':'')+gMetric('Margem prevista',pct(d.result,d.r),'Não é poupança realizada','','margin')+gMetric('Comprometimento',pct(d.out,d.r),'Saídas ÷ receitas','','commitment')+gMetric('Pendências de cadastro',String(d.pending.length),'Sem data ou com valor zero','','pending')+gMetric('Investimentos',fmt(d.investment),'Incluídos nas saídas e no resultado');$('gAlerts').innerHTML=gAlertHTML();gMain();$('gRanking').innerHTML=gRankingHTML();$('gHeat').innerHTML=gHeatHTML();$('gHistory').innerHTML=gHistoryHTML();$('gHistoryCaption').textContent=(gHistoryScope==='twelve'?'Consulta dos últimos 12 meses até o mês final, ignorando somente o intervalo de datas.':'Histórico limitado ao período aplicado.')+' Filtros de conteúdo e tipo de pessoa preservados. Verde: receitas; vermelho: saídas.';$('gUpdated').textContent='Análise atualizada em '+gUpdated;const tokens=Object.entries(gApplied).filter(([,v])=>v!=='').map(([k,v])=>'<span class="filtertoken">'+gNames[k]+': '+esc(['from','to'].includes(k)?br(v):v)+(!['from','to'].includes(k)?' <button data-g-remove="'+k+'" aria-label="Remover filtro">×</button>':'')+'</span>').join('');$('gActive').innerHTML='<b>Análise aplicada:</b> '+tokens+'<p>Modo: '+esc({period:'Análise do período',comparison:'Receitas × saídas',previous:'Mês anterior × atual',cash:'Evolução do caixa'}[gMode])+'. Tipo de pessoa: '+esc(entity())+'. Critério: vencimento.</p>';gRenderDetail();}
function gQuick(key){const ref=C.date(month+'-01');if(key==='previous')ref.setUTCMonth(ref.getUTCMonth()-1);if(key==='next')ref.setUTCMonth(ref.getUTCMonth()+1);const target=C.iso(ref).slice(0,7);let [start,end]=C.range(target);if(key==='semester'){const y=target.slice(0,4),first=Number(target.slice(5))<=6;start=y+'-'+(first?'01':'07')+'-01';end=y+'-'+(first?'06-30':'12-31');}if(key==='year'){start=target.slice(0,4)+'-01-01';end=target.slice(0,4)+'-12-31';}$('gFrom').value=start;$('gTo').value=end;gMarkDirty();}
function gSaveView(){openDialog('Salvar visão de Gráficos e Evoluções','<label class="field">Nome da visão<input id="gViewName" placeholder="Ex.: despesas de novembro"></label><p class="note">Salva a análise aplicada, não os campos ainda pendentes. A visão fica disponível nesta sessão de trabalho.</p>',()=>{const name=$('gViewName').value.trim();if(!name)throw Error('Informe um nome.');gViews[name]={filters:{...gApplied},mode:gMode,history:gHistoryScope,ranking:$('gRankingUnit').value,heat:$('gHeatKind').value};$('gSaved').innerHTML='<option value="">Escolha uma visão</option>'+Object.keys(gViews).map(n=>'<option>'+esc(n)+'</option>').join('');return 'Visão salva nesta sessão.';});}
function gPrintHTML(){const d=gData(),mode=$('gMainTitle').textContent;return '<h1>Gráficos e Evoluções</h1><p>'+esc(gFiltersText())+'</p><p>Emitido em '+esc(new Date().toLocaleString('pt-BR'))+' · análise atualizada em '+esc(gUpdated)+' · '+esc($('pf495GreetingTitle')?.textContent||'Planejamento Financeiro')+' / '+esc($('pf495PerfilBadge')?.textContent||'')+'</p><p><b>Critério: vencimento. Resultado não inclui abertura e não é saldo bancário conciliado.</b></p><table><tr><th>Indicador</th><th>Valor</th></tr>'+[['Receitas cadastradas',fmt(d.r)],['Receitas recebidas',fmt(d.received)],['Despesas cadastradas',fmt(d.d)],['Despesas pagas',fmt(d.paid)],['Investimentos',fmt(d.investment)],['Resultado previsto do período',fmt(d.result)],['Despesas a vencer',fmt(d.due)],['Despesas vencidas',fmt(d.late)],['Margem prevista (resultado ÷ receitas)',pct(d.result,d.r)],['Comprometimento (saídas ÷ receitas)',pct(d.out,d.r)]].map(([k,v])=>'<tr><td>'+k+'</td><td>'+v+'</td></tr>').join('')+'</table>'+gAlertHTML(true)+'<section class="print-section"><h2>'+esc(mode)+'</h2>'+$('gMainChart').innerHTML+'<p>'+esc($('gModeNote').textContent)+'</p><h2>Ranking de rubricas — saídas</h2>'+gRankingHTML(true)+'</section><section class="print-section"><h2>Concentração por vencimento</h2>'+gHeatHTML(true)+'<p>Destaque: maior saída diária. Verde indica receitas na visão opcional.</p><h2>Histórico de 12 meses</h2><p>'+esc($('gHistoryCaption').textContent)+'</p><div class="g-history">'+gHistoryHTML()+'</div><p>N/D: histórico não fornecido; Fora do recorte: mês não consultado; Sem registros: nenhum registro corresponde aos filtros em mês com cobertura. Zero exige registros com soma zero.</p></section><section class="print-section"><h2>Todos os lançamentos da análise aplicada</h2>'+gTable(d.active,false)+'<p>'+totals(d.active)+'</p><h2>Pendências de cadastro</h2>'+gTable(d.pending,false)+'<p>Corrigir datas/valores no cadastro original antes de interpretar os movimentos. Não foram excluídos registros automaticamente.</p></section><p>Origem: cadastro financeiro do usuário. Margem prevista não comprova poupança realizada. Filtros e modo são os da análise aplicada; alterações ainda não aplicadas não entram neste relatório.</p>';}
