document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const v=b.dataset;if(v.gPeriod)gQuick(v.gPeriod);if(v.gRemove){gApplied[v.gRemove]='';gFill(gApplied);gApply();}if(v.gSort){gSort={field:v.gSort,desc:gSort.field===v.gSort?!gSort.desc:false};gRenderDetail();}if(v.gEdit)edit(Number(v.gEdit));if(v.gCategory)gDrill(gData().active.filter(t=>t.tipo!=='Receita'&&t.categoria===v.gCategory).map(t=>t.id),'Rubrica: '+v.gCategory);if(v.gDate)gDrill(gData().active.filter(t=>t.vencimento===v.gDate).map(t=>t.id),'Vencimento: '+br(v.gDate));if(v.gDup!==undefined){const a=duplicates(gData().active)[Number(v.gDup)];if(a)gDrill(a.map(t=>t.id),'Conferência de registros semelhantes');}if(v.gDrill==='before'){const a=gData().active.filter(t=>!C.paid(t)&&t.vencimento>=cut()),next=a.filter(t=>t.tipo==='Receita').sort((a,b)=>a.vencimento.localeCompare(b.vencimento))[0];gDrill(a.filter(t=>t.tipo!=='Receita'&&next&&t.vencimento<next.vencimento).map(t=>t.id),'Pagamentos antes da próxima entrada');}if(v.gHelp==='margin')info('Margem prevista','<p>Resultado previsto ÷ receitas cadastradas × 100. É uma proporção do resultado do período, não poupança já realizada.</p><p>Receitas zeradas: margem N/D. Investimentos entram nas saídas e no resultado.</p>');if(v.gHelp==='commitment')info('Comprometimento','<p>Despesas e investimentos cadastrados ÷ receitas cadastradas × 100. Não mede cobertura por dinheiro disponível em banco.</p>');if(v.gHelp==='pending'){$('gDataIssues').scrollIntoView({behavior:'smooth'});}});

const restoredTypes={original:'Padrão (original)',bars:'Barras',line:'Linhas',area:'Áreas',pie:'Pizza (circular)'};
function restoredSeries(key){const d=gData(),sum=a=>a.reduce((n,t)=>n+C.cents(t),0),group=(a,fn)=>{const m=new Map();a.forEach(t=>{const k=fn(t);if(!m.has(k))m.set(k,[]);m.get(k).push(t);});return [...m].map(([label,items])=>({label,value:sum(items),ids:items.map(t=>t.id)}));};
if(key==='movement')return [{label:'Receitas',value:d.r,ids:d.rec.map(t=>t.id)},{label:'Saídas',value:-d.out,ids:d.active.filter(t=>t.tipo!=='Receita').map(t=>t.id)},{label:'Resultado do período',value:d.result,ids:d.active.map(t=>t.id)}];
if(key==='ranking')return group(d.active.filter(t=>t.tipo!=='Receita'),t=>t.categoria||'Sem rubrica').sort((a,b)=>b.value-a.value);
if(key==='late'){const a=d.active.filter(t=>t.tipo!=='Receita'&&!C.paid(t)&&t.vencimento<cut());return [[1,7,'1–7 dias'],[8,30,'8–30 dias'],[31,Infinity,'Mais de 30 dias']].map(([lo,hi,label])=>{const items=a.filter(t=>{const n=C.days(t.vencimento,cut());return n>=lo&&n<=hi;});return {label,value:sum(items),ids:items.map(t=>t.id)};});}
if(key==='heat')return group(d.active.filter(t=>t.tipo!=='Receita'),t=>t.vencimento).sort((a,b)=>a.label.localeCompare(b.label)).map(x=>({...x,label:br(x.label)}));
const rec=d.rec.filter(t=>!C.paid(t));return group(rec,t=>key==='incomeDate'?t.vencimento:t.descricao).sort((a,b)=>a.label.localeCompare(b.label)).map(x=>({...x,label:key==='incomeDate'?br(x.label):x.label}));}
const restoredSpecs=[['movement','Receitas, saídas e resultado do período'],['ranking','Ranking de rubricas — saídas'],['late','Vencidos por faixa de atraso'],['heat','Mapa de calor — saídas por dia'],['incomeDate','Receitas previstas por vencimento'],['incomeDescription','Receitas previstas por descrição']];
const restoredColors=['#16a085','#e35c73','#6e83c6','#d2a543','#9170cc','#44a6c7','#d18155','#71995d'];
function restoredChart(key,type){const a=restoredSeries(key),max=Math.max(1,...a.map(x=>Math.abs(x.value))),total=a.reduce((n,x)=>n+Math.max(0,x.value),0),click=(i)=>' data-restored-point="'+key+':'+i+'"';if(!a.length)return '<p>Sem lançamentos neste recorte.</p>';if(type==='pie'&&a.some(x=>x.value<0))return '<p>Pizza indisponível para valores negativos ou resultado derivado. Selecione Barras, Linhas ou Áreas.</p>';if(type==='pie'){if(!total)return '<p>Sem valores positivos para compor a pizza.</p>';let angle=0;return '<svg viewBox="0 0 760 280" role="img" aria-label="Gráfico de pizza">'+a.map((x,i)=>{const start=angle;angle+=Math.max(0,x.value)/total*Math.PI*2;const x1=135+105*Math.cos(start),y1=135+105*Math.sin(start),x2=135+105*Math.cos(angle),y2=135+105*Math.sin(angle);const shape=a.filter(z=>z.value>0).length===1?'<circle cx="135" cy="135" r="105"':'<path d="M135 135 L'+x1+' '+y1+' A105 105 0 '+(angle-start>Math.PI?1:0)+' 1 '+x2+' '+y2+' Z"';return '<g'+click(i)+' tabindex="0" role="button" aria-label="'+esc(x.label)+'">'+shape+' fill="'+restoredColors[i%8]+'"/><text x="270" y="'+(25+i*25)+'" fill="currentColor">'+esc(x.label)+' · '+fmt(x.value)+' ('+pct(x.value,total)+')</text></g>';}).join('')+'</svg>';}
if(type==='line'||type==='area'){const min=Math.min(0,...a.map(x=>x.value)),span=max-min||1,xx=i=>60+i*640/Math.max(1,a.length-1),yy=v=>205-(v-min)/span*170,points=a.map((x,i)=>xx(i)+','+yy(x.value)).join(' ');return '<svg viewBox="0 0 760 290" role="img" aria-label="'+(type==='line'?'Linhas':'Áreas')+'"><line x1="45" x2="725" y1="'+yy(0)+'" y2="'+yy(0)+'" stroke="currentColor" opacity=".4"/>'+(type==='area'?'<polygon points="60,'+yy(0)+' '+points+' '+xx(a.length-1)+','+yy(0)+'" fill="#44a6c7" opacity=".25"/>':'')+'<polyline points="'+points+'" fill="none" stroke="#44a6c7" stroke-width="3"/>'+a.map((x,i)=>'<g'+click(i)+' tabindex="0" role="button" aria-label="'+esc(x.label)+'"><circle cx="'+xx(i)+'" cy="'+yy(x.value)+'" r="6" fill="'+restoredColors[i%8]+'"/><text x="'+xx(i)+'" y="'+(yy(x.value)-12)+'" text-anchor="middle" fill="currentColor" font-size="12">'+fmt(x.value)+'</text><text x="'+xx(i)+'" y="235" text-anchor="middle" fill="currentColor" font-size="11">'+esc(x.label)+'</text></g>').join('')+'</svg>';}
return a.map((x,i)=>'<button class="g-rank-row"'+click(i)+'><div class="row"><span>'+esc(x.label)+'</span><b>'+fmt(x.value)+(key==='ranking'?' · '+pct(x.value,total):'')+'</b></div><div class="track"><span style="display:block;height:100%;width:'+Math.abs(x.value)/max*100+'%;background:'+(x.value<0?'#e35c73':restoredColors[i%8])+'"></span></div></button>').join('');}
