function desktopModel(base,active,start,end){base=base.filter(t=>['Receita','Despesa','Investimentos'].includes(t.tipo));active=active.filter(t=>t.vencimento&&C.cents(t)!==0);const opening=start?base.filter(t=>t.vencimento&&t.vencimento<start).reduce((s,t)=>s+C.signed(t),0):0;let acc=opening;const days=new Map();for(const t of active){if(!days.has(t.vencimento))days.set(t.vencimento,{date:t.vencimento,r:0,out:0});days.get(t.vencimento)[t.tipo==='Receita'?'r':'out']+=C.cents(t)}if(start&&end&&C.days(start,end)<=366&&start<=end)for(let d=start;d<=end;d=C.add(d,1))if(!days.has(d))days.set(d,{date:d,r:0,out:0});const daily=[...days.values()].sort((a,b)=>a.date.localeCompare(b.date)).map(d=>({...d,net:d.r-d.out,balance:acc+=d.r-d.out}));return{opening,closing:acc,daily,active,critical:daily.reduce((a,d)=>!a||d.balance<a.balance?d:a,null)}}
