function desktopFlowReport(){if(!authorized())return;revealAfterPasswordV5(()=>{if(!hasPageContent())return originalFlowReport();const m=currentModel(),a=m.active,sum=a=>a.reduce((n,t)=>n+C.cents(t),0),rec=a.filter(t=>t.tipo==='Receita'),out=a.filter(t=>t.tipo!=='Receita'),groups=new Map();out.forEach(t=>groups.set(t.categoria||'Sem rubrica',(groups.get(t.categoria||'Sem rubrica')||0)+C.cents(t)));const future=getFilteredTransactions({ignorarPeriodo:true,ignorarAtrasados:true}).filter(t=>!C.paid(t)&&t.vencimento>=cut()&&t.vencimento<=C.add(cut(),29));const pop=window.open('','_blank');if(!pop)return toast('Permita a nova aba para o relatório.');const html='<h1>Fluxo de caixa — recorte filtrado</h1><p>'+br($('filtroDataInicio').value)+' a '+br($('filtroDataFim').value)+' · Tipo de pessoa: '+esc(entity())+'</p><p>Emitido em '+new Date().toLocaleString('pt-BR')+'</p><p>'+esc(window.PFCashFlow.filters())+' · '+esc(Object.entries(pageItems).map(([k,v])=>k+': '+v).join(' · '))+'</p><p>Saldo inicial, final e mínimo: N/D. Os filtros de conteúdo selecionam movimentos e não definem disponibilidade de caixa. Valores por vencimento; não conciliados com extrato bancário.</p><h2>Movimentação do período</h2>'+gBars([{label:'Receitas',value:sum(rec)},{label:'Saídas',value:-sum(out)},{label:'Resultado do período',value:sum(rec)-sum(out)}])+'<h2>Saídas por rubrica</h2>'+gBars([...groups].sort((a,b)=>b[1]-a[1]).map(([label,value])=>({label,value})))+'<h2>Fluxo por data</h2><table><thead><tr><th>Data</th><th>Receitas</th><th>Saídas</th><th>Resultado do dia</th><th>Acumulado</th></tr></thead><tbody>'+m.daily.map(d=>'<tr><td>'+br(d.date)+'</td><td>'+fmt(d.r)+'</td><td>'+fmt(d.out)+'</td><td>'+fmt(d.net)+'</td><td>N/D</td></tr>').join('')+'</tbody></table><h2>Lançamentos do período</h2>'+gTable(a,false)+'<h2>Próximos 30 dias ('+br(cut())+' a '+br(C.add(cut(),29))+')</h2>'+gTable(future,false);pop.document.open();pop.document.write('<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Fluxo de caixa filtrado</title><style>'+reportStyles+':root{--green:#047857;--red:#bd2b20}.bar{margin:12px 0}.row{display:flex;justify-content:space-between}.track{height:12px;background:#edf2f8}.track span{display:block;height:100%}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Imprimir / salvar PDF</button>'+html+'</body></html>');pop.document.close()})}
